Added test plugin below:
```sourcepawn
#pragma newdecls required
#pragma semicolon 1

#include <base64>

public void OnPluginStart()
{
	RegServerCmd("sm_hello", Cmd_Base64);
}

public Action Cmd_Base64(int args)
{
	char testString[] = "hello world";
	char buffer[32];

	EncodeBase64(buffer, sizeof(buffer), testString);
	PrintToServer("Output of encoding string \"hello world\" into Base64: %s", buffer);

	char buffer2[32];
	DecodeBase64(buffer2, sizeof(buffer2), buffer);
	PrintToServer("Output of decoding string \"hello world\" from Base64: %s", buffer2);

	char buffer3[32];
	Base64MimeToUrl(buffer3, sizeof(buffer3), buffer);
	PrintToServer("Output of converting Base64 encoded string \"hello world\" to URL-compliant standard: %s", buffer3);

	char buffer4[32];
	Base64UrlToMime(buffer4, sizeof(buffer4), buffer3);
	PrintToServer("Output of converting URL-compliant Base64 encoded string \"hello world\" to MIME standard: %s", buffer4);

	return Plugin_Handled;
}
```

