var input = fs.readFileSync('dev/stdin').toString().split('\n');

const [n, m] = input[0].split(' ').map(num => parseInt(num));

var minCount = 8 * 8;
var maps = [];
for (r = 0; r < n; r++) {
    maps.push(input[r + 1].trim());
}

const whiteAns = [
    'WBWBWBWB',
    'BWBWBWBW',
    'WBWBWBWB',
    'BWBWBWBW',
    'WBWBWBWB',
    'BWBWBWBW',
    'WBWBWBWB',
    'BWBWBWBW',
];
const blackAns = [
    'BWBWBWBW',
    'WBWBWBWB',
    'BWBWBWBW',
    'WBWBWBWB',
    'BWBWBWBW',
    'WBWBWBWB',
    'BWBWBWBW',
    'WBWBWBWB',
]

for (r = 0; r < n-7; r++) {
    for (c = 0; c < m-7; c++) {
        var whiteCnt = 0;
        var blackCnt = 0;

        for (y = 0; y < 8; y++) {
            for (x = 0; x < 8; x++) {
                if (whiteAns[y][x] != maps[r + y][c + x]) {
                    whiteCnt += 1;
                }
                if (blackAns[y][x] != maps[r + y][c + x]) {
                    blackCnt += 1;
                }
            }
        }
        minCount = Math.min(minCount, whiteCnt, blackCnt);
    }
}

console.log(minCount);
```

